//! The harness corpus golden test: `tests/corpus/<harness>/<version>/` holds a store exactly as that
//! harness version wrote it (generated by `tools/harness-corpus/<harness>/generate.sh`, scrubbed),
//! and `summary.json` beside it is what cv read out of it. Every version stays forever, so this
//! test is the proof that cv still reads every format it ever read.
//!
//! A diff here is a parser behaviour change. If it is intended, regenerate the summaries with
//! `CV_REGEN_CORPUS=1 cargo test -p clustervision-core --test corpus` and explain the diff in the
//! commit. Never regenerate a version's store in place: add a new version directory instead.
//!
//! To add a harness: generate its corpus, then add one row to [`HARNESSES`] saying how to point its
//! adapter at a version directory.

use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};

use cv_core::harness::claude::Claude;
use cv_core::harness::cline::Cline;
use cv_core::harness::codex::Codex;
use cv_core::harness::continuedev::Continue;
use cv_core::harness::devin::Devin;
use cv_core::harness::gemini::Gemini;
use cv_core::harness::goose::Goose;
use cv_core::harness::grok::Grok;
use cv_core::harness::kimi::Kimi;
use cv_core::harness::kimi_code::KimiCode;
use cv_core::harness::openclaw::OpenClaw;
use cv_core::harness::opencode::OpenCode;
use cv_core::harness::qwen::Qwen;
use cv_core::harness::roo::Roo;
use cv_core::ir::{Block, MessageKind};
use cv_core::{Adapter, SessionRef};
use cv_testkit::World;
use serde_json::{json, Value};

/// How to read one harness's corpus: its directory name under `tests/corpus/`, and an adapter
/// rooted at a version directory (the store the generator copied, with the harness's own layout).
struct CorpusHarness {
    name: &'static str,
    adapter: fn(&Path) -> Box<dyn Adapter>,
    /// For a harness whose discovery lists only top-level sessions (sub-agents hang off the
    /// parent): the child refs of one discovered session, summarized under its `children`.
    children: Option<fn(&SessionRef) -> Vec<SessionRef>>,
}

fn codex(version_dir: &Path) -> Box<dyn Adapter> {
    Box::new(Codex::with_home(&version_dir.join(".codex")))
}

fn grok(version_dir: &Path) -> Box<dyn Adapter> {
    Box::new(Grok::with_home(&version_dir.join(".grok")))
}

fn claude_adapter(version_dir: &Path) -> Box<dyn Adapter> {
    Box::new(Claude::with_config_dir(&version_dir.join(".claude")))
}

/// Claude Code keeps each sub-agent (direct, and every workflow agent) in its own transcript under
/// the parent's `subagents/`, found the way `cv show --tree` finds them.
fn claude_children(r: &SessionRef) -> Vec<SessionRef> {
    cv_core::harness::claude::subagent_tree(&r.path)
        .into_iter()
        .map(|k| k.session)
        .collect()
}

fn opencode(version_dir: &Path) -> Box<dyn Adapter> {
    Box::new(OpenCode::with_data_dir(&version_dir.join(".local/share/opencode")))
}

fn kimi(version_dir: &Path) -> Box<dyn Adapter> {
    Box::new(Kimi::with_home(&version_dir.join(".kimi")))
}

fn kimi_code(version_dir: &Path) -> Box<dyn Adapter> {
    Box::new(KimiCode::with_home(&version_dir.join(".kimi-code")))
}

fn cline(version_dir: &Path) -> Box<dyn Adapter> {
    Box::new(Cline::with_home(version_dir))
}

fn continue_(version_dir: &Path) -> Box<dyn Adapter> {
    Box::new(Continue::with_root(&version_dir.join(".continue")))
}

fn devin(version_dir: &Path) -> Box<dyn Adapter> {
    Box::new(Devin::with_root(&version_dir.join(".local/share/devin/cli")))
}

fn roo(version_dir: &Path) -> Box<dyn Adapter> {
    Box::new(Roo::with_home(version_dir))
}

fn gemini(version_dir: &Path) -> Box<dyn Adapter> {
    Box::new(Gemini::with_home(&version_dir.join(".gemini")))
}

fn qwen(version_dir: &Path) -> Box<dyn Adapter> {
    Box::new(Qwen::with_home(&version_dir.join(".qwen")))
}

fn goose(version_dir: &Path) -> Box<dyn Adapter> {
    Box::new(Goose::with_sessions_dir(&version_dir.join("sessions")))
}

/// The version dir IS the state dir: `agents/` (JSONL era and sqlite era alike), plus the
/// sub-agent and cron registries the adapter does not read.
fn openclaw(version_dir: &Path) -> Box<dyn Adapter> {
    Box::new(OpenClaw::with_state_dir(version_dir))
}

/// Harnesses that cannot be driven headless (desktop apps): their version dirs hold a schema
/// snapshot of the store ember's installed version left on disk (`SNAPSHOT.toml` plus the
/// `*.schema.txt` / `*.shape.txt` that `tools/harness-corpus/schema_snapshot.py` wrote), never
/// sessions. `tools/harness-corpus/<h>/snapshot.sh --check` is what detects a change.
const SNAPSHOT_ONLY: &[&str] = &["lmstudio", "zed"];

const HARNESSES: &[CorpusHarness] = &[
    CorpusHarness {
        name: "claude",
        adapter: claude_adapter,
        children: Some(claude_children),
    },
    CorpusHarness {
        name: "cline",
        adapter: cline,
        children: None,
    },
    CorpusHarness {
        name: "codex",
        adapter: codex,
        children: None,
    },
    CorpusHarness {
        name: "continue",
        adapter: continue_,
        children: None,
    },
    CorpusHarness {
        name: "devin",
        adapter: devin,
        children: None,
    },
    CorpusHarness {
        name: "gemini",
        adapter: gemini,
        children: None,
    },
    CorpusHarness {
        name: "grok",
        adapter: grok,
        children: None,
    },
    CorpusHarness {
        name: "opencode",
        adapter: opencode,
        children: None,
    },
    CorpusHarness {
        name: "kimi",
        adapter: kimi,
        children: Some(cv_core::harness::kimi::subagent_refs),
    },
    CorpusHarness {
        name: "kimi-code",
        adapter: kimi_code,
        children: Some(cv_core::harness::kimi_code::subagent_refs),
    },
    CorpusHarness {
        name: "qwen",
        adapter: qwen,
        children: None,
    },
    CorpusHarness {
        name: "roo",
        adapter: roo,
        children: None,
    },
    CorpusHarness {
        name: "goose",
        adapter: goose,
        children: None,
    },
    CorpusHarness {
        name: "openclaw",
        adapter: openclaw,
        children: None,
    },
];

fn corpus_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/corpus")
}

fn subdirs(dir: &Path) -> Vec<PathBuf> {
    let mut v: Vec<PathBuf> = fs::read_dir(dir)
        .unwrap_or_else(|e| panic!("reading {}: {e}", dir.display()))
        .filter_map(|e| e.ok().map(|e| e.path()))
        .filter(|p| p.is_dir())
        .collect();
    v.sort();
    v
}

fn block_type(b: &Block) -> &'static str {
    match b {
        Block::Text { .. } => "text",
        Block::Thinking { .. } => "thinking",
        Block::ToolUse { .. } => "tool_use",
        Block::ToolResult { .. } => "tool_result",
        Block::Image { .. } => "image",
        Block::File { .. } => "file",
    }
}

fn tag(v: impl serde::Serialize) -> String {
    serde_json::to_value(v).unwrap().as_str().unwrap_or("?").to_string()
}

/// The stable, comparable part of one parsed session.
fn summarize_one(adapter: &dyn Adapter, r: &SessionRef, version_dir: &Path) -> Value {
    let s = adapter
        .parse(r)
        .unwrap_or_else(|e| panic!("parsing {}: {e:#}", r.path.display()));
    let mut blocks: BTreeMap<&str, usize> = BTreeMap::new();
    let mut tools = Vec::new();
    for m in &s.messages {
        for b in &m.content {
            *blocks.entry(block_type(b)).or_default() += 1;
            if let Block::ToolUse { name, namespace, .. } = b {
                tools.push(match namespace {
                    Some(ns) => format!("{ns}/{name}"),
                    None => name.clone(),
                });
            }
        }
    }
    let indices = |k: MessageKind| -> Vec<usize> {
        s.messages
            .iter()
            .enumerate()
            .filter(|(_, m)| m.kind == k)
            .map(|(i, _)| i)
            .collect()
    };
    json!({
        "id": s.id,
        "path": r.path.strip_prefix(version_dir).unwrap_or(&r.path),
        "messages": s.messages.len(),
        "sequence": s.messages.iter().map(|m| format!("{}/{}", tag(m.role), tag(m.kind))).collect::<Vec<_>>(),
        "blocks": blocks,
        "tools": tools,
        "usage_messages": s.messages.iter().filter(|m| m.usage.is_some()).count(),
        "compaction_boundaries": indices(MessageKind::CompactionBoundary),
        "subagent_spawns": indices(MessageKind::SubagentSpawn).len(),
        "subagent_returns": indices(MessageKind::SubagentReturn).len(),
        "lineage": s.lineage,
        "model": s.model,
        "skipped_lines": s.cv_extra().and_then(|c| c.get("skipped_lines")).cloned().unwrap_or(json!(0)),
    })
}

/// Every discovered session of one version directory, with its children where the harness has any.
fn summarize(h: &CorpusHarness, version_dir: &Path) -> Value {
    let adapter = (h.adapter)(version_dir);
    let mut refs = adapter.discover().expect("discover");
    refs.sort_by(|a, b| a.id.cmp(&b.id));
    let sessions: Vec<Value> = refs
        .iter()
        .map(|r| {
            let mut one = summarize_one(adapter.as_ref(), r, version_dir);
            if let Some(children) = h.children {
                let mut kids = children(r);
                kids.sort_by(|a, b| a.id.cmp(&b.id));
                one["children"] = kids
                    .iter()
                    .map(|k| summarize_one(adapter.as_ref(), k, version_dir))
                    .collect();
            }
            one
        })
        .collect();
    json!({ "sessions": sessions })
}

#[test]
fn every_corpus_version_reads_as_its_golden_summary() {
    // In-process world: discovery's scan cache lives in $CLUSTERVISION_HOME, never the real one.
    let _w = World::in_process("corpus");
    let regen = std::env::var_os("CV_REGEN_CORPUS").is_some();
    let known: Vec<&str> = HARNESSES.iter().map(|h| h.name).collect();
    for dir in subdirs(&corpus_root()) {
        let name = dir.file_name().unwrap().to_str().unwrap();
        if SNAPSHOT_ONLY.contains(&name) {
            for v in subdirs(&dir) {
                assert!(v.join("SNAPSHOT.toml").is_file(), "{}: no SNAPSHOT.toml", v.display());
            }
            continue;
        }
        assert!(known.contains(&name), "tests/corpus/{name} has no row in HARNESSES");
    }
    let mut failures = Vec::new();
    for h in HARNESSES {
        let versions = subdirs(&corpus_root().join(h.name));
        assert!(!versions.is_empty(), "no corpus versions for {}", h.name);
        for v in versions {
            let label = format!("{}/{}", h.name, v.file_name().unwrap().to_string_lossy());
            assert!(v.join("MANIFEST.toml").is_file(), "{label}: no MANIFEST.toml");
            let got = summarize(h, &v);
            assert!(
                !got["sessions"].as_array().unwrap().is_empty(),
                "{label}: the adapter found no sessions"
            );
            let path = v.join("summary.json");
            let text = serde_json::to_string_pretty(&got).unwrap() + "\n";
            if regen {
                fs::write(&path, &text).unwrap();
                continue;
            }
            let want =
                fs::read_to_string(&path).unwrap_or_else(|e| panic!("{label}: {e} (CV_REGEN_CORPUS=1 writes it)"));
            if want != text {
                failures.push(format!(
                    "{label}: summary differs from {}\n--- got:\n{text}",
                    path.display()
                ));
            }
        }
    }
    assert!(
        failures.is_empty(),
        "cv reads the corpus differently than recorded (CV_REGEN_CORPUS=1 rewrites; explain the diff):\n{}",
        failures.join("\n")
    );
}

/// Nothing secret or personal in any committed corpus file: GitHub push protection rejects
/// real-looking tokens, and a secret-shaped string in a fixture breaks releases.
#[test]
fn no_corpus_file_carries_a_secret_or_a_real_path() {
    let patterns = [
        r"sk-[A-Za-z0-9_-]{20,}",
        r"gh[pousr]_[A-Za-z0-9]{30,}",
        r"github_pat_[A-Za-z0-9_]{30,}",
        r"xox[abpr]-[A-Za-z0-9-]{10,}",
        r"AKIA[0-9A-Z]{16}",
        r"AIza[0-9A-Za-z_-]{35}",
        r"[Bb]earer [A-Za-z0-9._~+/-]{20,}",
        r"eyJ[A-Za-z0-9_-]{10,}\.eyJ[A-Za-z0-9_-]{10,}\.",
        r"[0-9a-f]{32}\.[A-Za-z0-9]{16}",
        r"/Users/[A-Za-z]",
        r"[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+\.(com|net|org|io|dev|ai|software)\b",
    ];
    let res: Vec<regex::bytes::Regex> = patterns.iter().map(|p| regex::bytes::Regex::new(p).unwrap()).collect();
    let mut bad = Vec::new();
    let mut n = 0;
    for e in walkdir::WalkDir::new(corpus_root()).into_iter().filter_map(|e| e.ok()) {
        if !e.file_type().is_file() {
            continue;
        }
        n += 1;
        let bytes = fs::read(e.path()).unwrap();
        for (p, re) in patterns.iter().zip(&res) {
            if re.is_match(&bytes) {
                bad.push(format!("{} matches {p}", e.path().display()));
            }
        }
    }
    assert!(n > 0, "no corpus files found");
    assert!(
        bad.is_empty(),
        "corpus files carry secret- or path-shaped text:\n{}",
        bad.join("\n")
    );
}

/// Claude Code keeps a `Workflow` run's state beside the transcript (`workflows/wf_<run>.json`) and
/// each agent's journaled result in `subagents/workflows/<run>/journal.jsonl`; the summary's
/// `children` has the agents' transcripts but neither of those. This reads them for every Claude
/// version through `claude_workflow::workflows` and `subagent_tree` into `workflows.json`, and checks
/// that every `agent-*.jsonl` on disk is one of the summary's children. `CV_REGEN_CORPUS=1` rewrites.
#[test]
fn claude_corpus_workflow_runs_read_as_recorded() {
    use cv_core::harness::{claude, claude_workflow};
    let _w = World::in_process("corpus-workflows");
    let regen = std::env::var_os("CV_REGEN_CORPUS").is_some();
    let mut failures = Vec::new();
    for v in subdirs(&corpus_root().join("claude")) {
        let label = format!("claude/{}", v.file_name().unwrap().to_string_lossy());
        let mut refs = claude_adapter(&v).discover().expect("discover");
        refs.sort_by(|a, b| a.id.cmp(&b.id));
        let children: usize = refs.iter().map(|r| claude_children(r).len()).sum();
        let on_disk = walkdir::WalkDir::new(&v)
            .into_iter()
            .filter_map(|e| e.ok())
            .filter(|e| {
                let n = e.file_name().to_string_lossy();
                n.starts_with("agent-") && n.ends_with(".jsonl")
            })
            .count();
        assert_eq!(children, on_disk, "{label}: subagent_tree missed sub-agent transcripts");
        let sessions: Vec<Value> = refs
            .iter()
            .filter_map(|r| {
                let runs: Vec<Value> = claude_workflow::workflows(&r.path)
                    .iter()
                    .map(|w| {
                        let mut agents: Vec<Value> = claude::subagent_tree(&r.path)
                            .iter()
                            .filter(|k| k.workflow.as_deref() == Some(w.run_id.as_str()))
                            .map(|k| json!({"agent_id": k.agent_id(), "result_status": k.result_status, "result_summary": k.result_summary}))
                            .collect();
                        agents.sort_by_key(|a| a["agent_id"].as_str().unwrap_or("").to_string());
                        json!({
                            "name": w.name,
                            "status": w.status,
                            "agent_count": w.agent_count,
                            "phases": w.phases.iter().map(|p| json!({"title": p.title, "agents": p.agents.len()})).collect::<Vec<_>>(),
                            "script": w.script.is_some(),
                            "journal": agents,
                        })
                    })
                    .collect();
                (!runs.is_empty()).then(|| json!({ "id": r.id, "workflows": runs }))
            })
            .collect();
        let text = serde_json::to_string_pretty(&json!({ "sessions": sessions })).unwrap() + "\n";
        let path = v.join("workflows.json");
        if regen {
            fs::write(&path, &text).unwrap();
            continue;
        }
        let want = fs::read_to_string(&path).unwrap_or_else(|e| panic!("{label}: {e} (CV_REGEN_CORPUS=1 writes it)"));
        if want != text {
            failures.push(format!(
                "{label}: workflows differ from {}\n--- got:\n{text}",
                path.display()
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
